"use client";

import { useGT, useMessages } from "gt-next/client";

type Gt = ReturnType<typeof useGT>;
type M = ReturnType<typeof useMessages>;

/**
 * Translates a validation issue for display. Built-in zod issues are mapped
 * by `code` (their English messages are generated by zod and never extracted),
 * custom issues carry an `msg()`-registered source string that `m` translates.
 */
export function formIssueMessage(error: unknown, gt: Gt, m: M): string | undefined {
  if (typeof error === "string") return m(error);
  if (!error || typeof error !== "object") return undefined;
  const issue = error as Record<string, unknown>;
  const origin = issue["origin"];
  const minimum = issue["minimum"];
  const maximum = issue["maximum"];
  switch (issue["code"]) {
    case "too_small":
      if (origin === "string" && minimum === 1) return gt("This field is required");
      if (origin === "string") {
        return gt("Must be at least {minimum} characters", { minimum: String(minimum) });
      }
      if (origin === "number") return gt("Must be at least {minimum}", { minimum: String(minimum) });
      break;
    case "too_big":
      if (origin === "string") {
        return gt("Must be at most {maximum} characters", { maximum: String(maximum) });
      }
      if (origin === "number") return gt("Must be at most {maximum}", { maximum: String(maximum) });
      break;
    case "invalid_type":
      if (issue["expected"] === "int") return gt("Enter a whole number");
      if (issue["expected"] === "number") return gt("Enter a number");
      return gt("Enter a valid value");
    case "invalid_format":
      if (issue["format"] === "email") return gt("Enter a valid email address");
      if (issue["format"] === "url") return gt("Enter a valid URL");
      return gt("Enter a value in the expected format");
    case "invalid_value":
      return gt("Choose a valid option");
    case "invalid_union":
      return gt("Enter a valid value");
    case "not_multiple_of":
      return gt("Enter a whole number");
  }
  const message = issue["message"];
  return typeof message === "string" ? m(message) : undefined;
}

export function FormFieldErrors({
  errors,
  visible,
}: {
  errors: readonly unknown[];
  visible: boolean;
}) {
  const gt = useGT();
  const m = useMessages();
  const messages = [
    ...new Set(
      errors.flatMap((error) => {
        const message = formIssueMessage(error, gt, m);
        return message ? [message] : [];
      }),
    ),
  ];

  if (!visible || messages.length === 0) return null;
  return (
    <div className="space-y-1 text-sm text-destructive" role="alert">
      {messages.map((message) => (
        <p key={message}>{message}</p>
      ))}
    </div>
  );
}
